import{_ as t,o as a,c as s,ah as i}from"./chunks/framework.BsNNkeaH.js";const g=JSON.parse('{"title":"Activités extrascolaires","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/vie-scolaire/activites-extrascolaires.md","filePath":"src/guide/vie-scolaire/activites-extrascolaires.md"}'),r={name:"guide/vie-scolaire/activites-extrascolaires.md"};function n(o,e,c,l,u,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="activites-extrascolaires" tabindex="-1">Activités extrascolaires <a class="header-anchor" href="#activites-extrascolaires" aria-label="Permalink to &quot;Activités extrascolaires&quot;">​</a></h1><p>Cette page couvre le pointage des présences aux séances d&#39;activités extrascolaires (piscine, théâtre, etc.). Les activités et leurs séances sont créées par l&#39;administrateur — voir <a href="/guide/admin/activites-extrascolaires.html">Activités extrascolaires (administration)</a> — cette page-ci ne couvre que le pointage des présences.</p><h2 id="faire-l-appel-a-une-seance" tabindex="-1">Faire l&#39;appel à une séance <a class="header-anchor" href="#faire-l-appel-a-une-seance" aria-label="Permalink to &quot;Faire l&#39;appel à une séance&quot;">​</a></h2><ol><li>Ouvrez <strong>Vie scolaire → Présences périscolaires</strong>. La liste affiche les séances planifiées, avec l&#39;activité, le site, le département et le jour/horaire de la séance.</li><li>Cliquez sur <strong>Faire l&#39;appel</strong> sur la séance concernée.</li><li>Changez la date en haut de page si vous devez pointer une autre occurrence de la séance que celle du jour en cours.</li><li>Pour chaque élève inscrit au niveau de cette séance sur ce site, touchez <strong>Présent</strong> ou <strong>Absent</strong>.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Si aucune séance n&#39;est planifiée, ou si aucun élève n&#39;est inscrit dans le niveau concerné sur ce site, la page l&#39;indique.</p><div class="tip custom-block"><p class="custom-block-title">Un pointage pensé pour le téléphone</p><p>Chaque élève a son bouton <strong>Présent</strong> / <strong>Absent</strong> ; tout le monde est <strong>Présent</strong> par défaut, et le bouton <strong>Tous présents</strong> remet toute la liste à ce statut. Les compteurs en haut de liste se mettent à jour à chaque clic, et la barre du bas signale « Modifications non enregistrées » tant que vous n&#39;avez pas cliqué sur <strong>Enregistrer</strong> — quitter la page ou changer de date à ce moment-là demande confirmation. Un pointage ne peut pas être saisi pour une date future.</p></div>',6)])])}const v=t(r,[["render",n]]);export{g as __pageData,v as default};
